// Cap on concurrent sessions — failsafe against missed disconnect events.
const MAX_SESSIONS = 1000;
const sessions = flow.get('sessions') || {};

const evt = msg && msg.uibuilderCtrl;
const sid = msg && msg._socketId;
if (!sid) return null;

if (evt === 'client connect') {
    if (Object.keys(sessions).length >= MAX_SESSIONS) {
        // Prune oldest 10% to make room.
        const entries = Object.entries(sessions).sort((a, b) => (a[1].connectedAt || 0) - (b[1].connectedAt || 0));
        const drop = entries.slice(0, Math.ceil(MAX_SESSIONS * 0.1));
        for (const [k] of drop) delete sessions[k];
        node.warn('sessions cap hit; pruned oldest ' + drop.length);
    }
    sessions[sid] = {
        connectedAt: Date.now(),
        conversationHistory: [],
        messageCount: 0,
        preferences: {}
    };
    flow.set('sessions', sessions);
    node.log('session connect: ' + sid + ' (n=' + Object.keys(sessions).length + ')');
} else if (evt === 'client disconnect') {
    if (sessions[sid]) {
        delete sessions[sid];
        flow.set('sessions', sessions);
        node.log('session disconnect: ' + sid);
    }
}
// 'ready' and other control events are no-ops here.
return null;

const action = msg._req && msg._req.action;
if (action !== 'bootstrap.session') {
    msg._result = { ok: false, errors: { action: 'bootstrap: unknown action: ' + action } };
    return msg;
}

const sid = msg._socketId;
const sessions = flow.get('sessions') || {};
const entry = sid && sessions[sid];

// Build initial view-model. Pulls latest known KPI snapshot, recent alerts,
// and conversation history. Phase 5 expands this with smart-city / data-products
// initial summaries. Returns a sessionId so the client persists it (FAP §11).
const alerts = (global.get('alerts') || []).slice(-20).reverse();
const engine = global.get('engine') || {};

msg._sessionId = sid;
msg._result = {
    ok: true,
    next: { step: 'dashboard' },
    data: {
        sessionId: sid,
        connectedAt: entry ? entry.connectedAt : Date.now(),
        engine_state: engine.state || 'unknown',
        recent_alerts: alerts,
        conversation_history: entry ? entry.conversationHistory : []
    }
};
return msg;

const sessions = flow.get('sessions') || {};
const rows = Object.entries(sessions).map(([socketId, s]) => ({
    socketId,
    connectedAt: s.connectedAt,
    messageCount: s.messageCount || 0
}));
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
msg.payload = { count: rows.length, sessions: rows };
return msg;

const sessions = flow.get('sessions') || {};
const cutoff = Date.now() - 60 * 60 * 1000;  // 1h
const before = Object.keys(sessions).length;
for (const [sid, s] of Object.entries(sessions)) {
    if (!s.connectedAt || s.connectedAt < cutoff) delete sessions[sid];
}
const after = Object.keys(sessions).length;
if (after < before) {
    flow.set('sessions', sessions);
    node.log('watchdog: pruned ' + (before - after) + ' stale sessions; ' + after + ' remain');
}
return null;
